    /// **A CLICK ON THE PANE MOVES THE CURSOR TO THE ROW IT IS ON.**
    ///
    /// The operator's second report about this pane, in leticl's `todos-stops` docstring: *"mouse
    /// doesnt click"*. letibot had no click arm for this pane at all — the picker and the mode card
    /// had one and the todos pane had none — and leticl's own first cut had one that computed the
    /// add row as a negative index and threw the click away.
    ///
    /// What makes it work is the row the pane RECORDED as it drew, not arithmetic at the click's
    /// end: a click has a screen row and nothing else, and a second computation of where a row went
    /// is the defect both reports came from.
    #[test]
    fn a_click_on_the_todos_pane_puts_the_cursor_on_the_row_it_is_on() {
        let dir = std::env::temp_dir().join(format!(
            "letibot-todo-click-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("scratch");
        std::fs::write(
            dir.join("TODO.md"),
            "## Phase 0\n\n- [x] **T1** first item\n- [ ] **T2** second item\n",
        )
        .expect("write");
        let mut a = app();
        a.wiring.workspace = dir.display().to_string();
        a.key(Key::CtrlP);

        // The screen's own rows, which is what a click's `y` names. No session is attached, so
        // there is no header above the pane and row N of the screen is row N of the pane.
        let row_of = |screen: &[String], what: &str| {
            u16::try_from(
                screen
                    .iter()
                    .position(|l| l.contains(what))
                    .unwrap_or_else(|| panic!("no row with {what:?} in:\n{}", screen.join("\n"))),
            )
            .expect("fits")
        };
        // **The screen is an argument and not a capture** — a closure over the frame the test
        // happened to take first is a test that passes and fails for reasons nothing to do with
        // the click, which is how this one first read as a broken click.
        let marked = |screen: &[String], what: &str| {
            screen
                .iter()
                .find(|l| l.contains('▸'))
                .is_some_and(|l| l.contains(what))
        };
        let screen = a.screen(110, 40);
        assert!(
            marked(&screen, "[+] add todo item"),
            "starts on the control"
        );

        // A click on the second item's row moves the cursor to it, and stops there: select and
        // confirm stay two acts, as they do in the pickers.
        a.key(Key::Click {
            x: 6,
            y: row_of(&screen, "T2 second item"),
        });
        let screen = a.screen(110, 40);
        assert!(
            marked(&screen, "T2 second item"),
            "the click moved the mark:\n{}",
            screen.join("\n")
        );
        assert_eq!(a.repo_sel, 2, "and the repo cursor followed");
        assert_eq!(a.key(Key::Enter), None);
        let screen = a.screen(110, 40);
        assert!(
            marked(&screen, "T2 second item"),
            "the click did not confirm:\n{}",
            screen.join("\n")
        );

        // A click on the add control — **the row `line - header` used to make negative** — lands
        // on it, which is the whole of the operator's report.
        a.key(Key::Click {
            x: 6,
            y: row_of(&screen, "[+] add todo item"),
        });
        let screen = a.screen(110, 40);
        assert!(
            marked(&screen, "[+] add todo item"),
            "the control takes a click:\n{}",
            screen.join("\n")
        );

        // A click on the `## Phase 0` heading moves nothing: it is drawn and is not a stop, and no
        // key would act on it.
        a.key(Key::Click {
            x: 6,
            y: row_of(&screen, "Phase 0"),
        });
        let screen = a.screen(110, 40);
        assert!(
            marked(&screen, "[+] add todo item"),
            "a heading is not a stop: a click there moves nothing:\n{}",
            screen.join("\n")
        );

        // And a click into the blank space below the list moves nothing either — the guard is the
        // WINDOW, not the list.
        let below = row_of(&screen, "this pane never writes it");
        a.key(Key::Click { x: 6, y: below });
        let screen = a.screen(110, 40);
        assert!(
            marked(&screen, "[+] add todo item"),
            "blank space below the rows moves nothing:\n{}",
            screen.join("\n")
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn the_todos_pane_shows_both_sources_and_says_which_is_which() {
        let mut a = app();
        // The session's list, as the event carried it.
        a.apply(ServerFrame::Event(env(
            1,
            SessionEvent::TodosUpdated {
                todos: vec![
                    letibot_sessionlog::event::TodoEntry {
                        by: letibot_sessionlog::event::TodoBy::Model,
                        content: "seat the tool".into(),
                        status: letibot_sessionlog::event::TodoStatus::Completed,
                    },
                    letibot_sessionlog::event::TodoEntry {
                        by: letibot_sessionlog::event::TodoBy::Model,
                        content: "render the pane".into(),
                        status: letibot_sessionlog::event::TodoStatus::InProgress,
                    },
                ],
            },
        )));
        // The repo's queue, as the pane-open read found it. Pointed at this
        // workspace, which has a real TODO.md with sections and checkboxes.
        a.wiring.workspace = std::env::var("CARGO_MANIFEST_DIR")
            .map(|d| {
                std::path::Path::new(&d)
                    .parent()
                    .unwrap()
                    .parent()
                    .unwrap()
                    .display()
                    .to_string()
            })
            .unwrap_or_default();
        a.key(Key::CtrlP);
        let screen = a.screen(110, 40).join("\n");
        assert!(screen.contains("[x] seat the tool"), "{screen}");
        assert!(screen.contains("[~] render the pane"), "{screen}");
        assert!(
            screen.contains("TODO.md"),
            "the second source is named: {screen}"
        );
        // A heading carries org's cookie rather than a sentence of counts, and —
        // the point — the items under it are actually drawn.
        assert!(
            screen.contains("/") && screen.contains("["),
            "headings carry a [done/total] cookie: {screen}"
        );
    }

    /// **The new-todo card: title, Tab for the detail, Enter adds it as yours, Esc cancels** —
    /// leticl's `todo-card-lines`, and the shape its `%todo-draft-*` keys keep.
    ///
    /// **The composer is the field.** Tab stores what was typed into the field being left and puts
    /// the other one in the composer, so the field under the cursor is never a keystroke behind —
    /// and everything else is the editor's, so the title and the detail are typed, pasted and
    /// undone with the keys the operator already has.
    ///
    /// **A title is required and the card stays up without one**, which is the only field rule: a
    /// row of nothing is not what the reader meant, and saying so beats storing it.
    #[test]
    fn the_todo_card_takes_a_title_and_a_detail_and_adds_them_as_yours() {
        use letibot_sessionlog::event::TodoBy;
        let mut a = app();
        a.apply(hello("s", vec![brief("s", "one", false)], Hub::new("s").snapshot()));
        assert_eq!(a.command("todo"), None, "bare /todo opens the card");
        assert!(a.todo_draft.is_some());
        // The card is drawn with its three keys, which is how a reader learns Tab exists.
        let card = a.screen(100, 30).join("\n");
        assert!(card.contains("adding a todo item"), "{card}");
        assert!(card.contains("moves between the fields"), "{card}");

        // **A title alone.** Type it and press Enter.
        typed(&mut a, "ship the parity row");
        assert!(matches!(a.key(Key::Enter), Some(Action::SetOperatorTodos(_))));
        assert!(a.todo_draft.is_none(), "the card came down");
        assert_eq!(a.input(), "", "and the composer is empty again");

        // **An empty title is refused and the card STAYS UP**, which is the one field rule.
        a.command("todo");
        assert!(matches!(a.key(Key::Enter), None));
        assert!(
            a.todo_draft.is_some(),
            "the card came down on an empty title"
        );
        assert!(
            a.notice.as_deref().unwrap_or("").contains("needs a title"),
            "{:?}",
            a.notice
        );

        // **Tab moves to the detail and back, keeping both.** The composer carries the focused
        // field; the draft carries the other.
        typed(&mut a, "and the cache too");
        a.key(Key::Tab);
        assert_eq!(
            a.input(),
            "",
            "the detail field is empty when it is entered"
        );
        typed(&mut a, "the note the model needs");
        a.key(Key::Tab);
        assert_eq!(
            a.input(),
            "and the cache too",
            "Tab came back to the title, with what was typed into it"
        );

        // **Enter adds both, tagged as the operator's.**
        let act = a.key(Key::Enter);
        match act {
            Some(Action::SetOperatorTodos(items)) => {
                assert_eq!(items.len(), 1);
                assert_eq!(items[0].by, TodoBy::Operator);
                assert!(
                    items[0].content.contains("and the cache too")
                        && items[0].content.contains("the note the model needs"),
                    "the detail was lost: {:?}",
                    items[0].content
                );
            }
            other => panic!("expected the add, got {other:?}"),
        }

        // **Esc cancels and adds nothing** — the card asks, and a question has to be able to be
        // answered no.
        a.command("todo");
        typed(&mut a, "never mind");
        assert_eq!(a.key(Key::Esc), None);
        assert!(a.todo_draft.is_none(), "esc did not close the card");
        assert_eq!(a.input(), "", "and took the words with it");
        assert!(
            a.notice.as_deref().unwrap_or("").contains("nothing added"),
            "{:?}",
            a.notice
        );
    }

    /// **The operator can add a row of their own, and it goes to the daemon as their half.**
    ///
    /// The gap this closes, measured before writing it: **`TodoBy::Operator` was constructible
    /// only in tests.** The daemon stores and serves the operator's rows, the pane splits them out,
    /// and nothing in the tree could CREATE one — `ClientFrame::SetOperatorTodos` had no sender at
    /// all, though the protocol's own doc describes a head sending one. So the operator's half of
    /// the board was unreachable, and *"you dont support persistent todos and leticl does"* was
    /// exactly right.
    #[test]
    fn the_operator_can_add_and_dispose_of_their_own_todo_rows() {
        use letibot_sessionlog::event::{TodoBy, TodoEntry, TodoStatus};
        let mut a = app();
        a.apply(hello("s", vec![brief("s", "one", false)], Hub::new("s").snapshot()));
        // A row the MODEL wrote, so the numbering can be shown to be over the operator's half only.
        a.apply(ServerFrame::Event(env(1, SessionEvent::TodosUpdated {
            todos: vec![TodoEntry {
                content: "the model's own row".into(),
                status: TodoStatus::Pending,
                by: TodoBy::Model,
            }],
        })));
        let mine = |a: &App| a.operator_todos();

        // **Adding one sends the WHOLE list, tagged as the operator's.** There is no per-row frame.
        let act = a.command("todo ship the parity row");
        match &act {
            Some(Action::SetOperatorTodos(items)) => {
                assert_eq!(items.len(), 1, "the whole list is one row: {items:?}");
                assert_eq!(items[0].content, "ship the parity row");
                assert_eq!(items[0].by, TodoBy::Operator, "filed in the operator's half");
                assert_eq!(items[0].status, TodoStatus::Pending);
            }
            other => panic!("expected a SetOperatorTodos, got {other:?}"),
        }
        // The daemon takes it and publishes the union back — which is how the head learns its own
        // list: it keeps no second copy.
        a.apply(ServerFrame::Event(env(2, SessionEvent::TodosUpdated {
            todos: vec![
                TodoEntry {
                    content: "the model's own row".into(),
                    status: TodoStatus::Pending,
                    by: TodoBy::Model,
                },
                TodoEntry {
                    content: "ship the parity row".into(),
                    status: TodoStatus::Pending,
                    by: TodoBy::Operator,
                },
            ],
        })));
        assert_eq!(mine(&a).len(), 1, "the head sees its own row back");

        // **`done 1` marks the FIRST OF THE OPERATOR'S ROWS** — not the first of the union, which
        // is the model's. A number over the union would edit a row that is not theirs to edit.
        match a.command("todo done 1") {
            Some(Action::SetOperatorTodos(items)) => {
                assert_eq!(items.len(), 1);
                assert_eq!(items[0].content, "ship the parity row");
                assert_eq!(items[0].status, TodoStatus::Completed);
            }
            other => panic!("expected completion, got {other:?}"),
        }
        // **A number out of range is REFUSED by name**, not clamped onto a neighbour.
        assert_eq!(a.command("todo done 9"), None);
        assert!(
            a.notice.as_deref().unwrap_or("").contains("no row 9"),
            "the refusal does not name the row: {:?}",
            a.notice
        );
        // **`rm 1` takes it off**, which is the operator's own act and not the model's — the model
        // may move a row's status and may not remove it.
        match a.command("todo rm 1") {
            Some(Action::SetOperatorTodos(items)) => {
                assert!(items.is_empty(), "the row is gone: {items:?}");
            }
            other => panic!("expected a removal, got {other:?}"),
        }
        // **A bare `/todo` opens the CARD** — the shape `/mode` and `/models` keep, where an act
        // with more than one part is chosen from a card rather than typed blind.
        assert_eq!(a.command("todo"), None);
        assert!(
            a.todo_draft.is_some(),
            "bare /todo did not open the card: {:?}",
            a.notice
        );
    }

    /// **A row is drawn ONCE, under the author that wrote it** — R51 item 18, and the defect it
    /// records is the one leticl measured and handed back.
    ///
    /// The wire's list is the **union** (`TodoBoard::snapshot`: the model's rows, then the
    /// operator's), because that is what the model has to see. A pane that drew it under one
    /// heading therefore showed the operator's rows **as the model's plan** — on leticl's head the
    /// same row appeared twice with two different authors:
    ///
    /// ```text
    /// [x] push leticl to github  — you
    /// [x] push leticl to github  — model
    /// ```
    ///
    /// a duplicate AND a false author, from one row on the board. This asserts the two halves of
    /// the fix: each row once, and each under the heading of the half that owns it.
    #[test]
    fn a_todo_row_is_drawn_once_under_the_author_that_wrote_it() {
        use letibot_sessionlog::event::{TodoBy, TodoEntry, TodoStatus};
        let row = |content: &str, by| TodoEntry {
            by,
            content: content.into(),
            status: TodoStatus::Pending,
        };
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        // The union, in the order the daemon builds it: the model's half first.
        a.apply(ServerFrame::Event(env(
            1,
            SessionEvent::TodosUpdated {
                todos: vec![
                    row("seat the tool", TodoBy::Model),
                    row("push leticl to github", TodoBy::Operator),
                ],
            },
        )));
        a.todos_pane = true;
        let screen = a.screen(110, 40).join("\n");
        // **Once each.** The duplicate is the defect, so a count is the assertion.
        for content in ["seat the tool", "push leticl to github"] {
            assert_eq!(
                screen.matches(content).count(),
                1,
                "`{content}` is drawn more than once: {screen}"
            );
        }
        // **And each row wears its OWN author as a tag** — R51 item 18: *"the author tag on every
        // row is the requirement (R44)."* A heading was the earlier reading; a tag is the fact,
        // and a pane that re-derives authorship from which section a row landed in is the drift
        // the `by` field exists to prevent.
        let tool = screen
            .lines()
            .find(|l| l.contains("seat the tool"))
            .expect("the model's row is on the screen");
        assert!(
            tool.contains("— model"),
            "the model's row does not name its author: {tool:?}"
        );
        let push = screen
            .lines()
            .find(|l| l.contains("push leticl to github"))
            .expect("the operator's row is on the screen");
        assert!(
            push.contains("— you"),
            "the operator's row does not name its author: {push:?}"
        );
    }

    /// **An empty half says which half is empty** — the two sentences are not the same statement.
    ///
    /// A session whose plan the operator has taken over has no model rows and several of their own;
    /// one where the model has written a plan has none of theirs. `none written yet` over a list the
    /// MODEL is supposed to be keeping and over a list the OPERATOR owns are different facts about
    /// different halves, and this is the split that makes saying so possible.
    #[test]
    fn each_half_of_the_board_says_when_it_is_the_empty_one() {
        use letibot_sessionlog::event::{TodoBy, TodoEntry, TodoStatus};
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        a.apply(ServerFrame::Event(env(
            1,
            SessionEvent::TodosUpdated {
                todos: vec![TodoEntry {
                    by: TodoBy::Operator,
                    content: "my own row".into(),
                    status: TodoStatus::Pending,
                }],
            },
        )));
        a.todos_pane = true;
        let screen = a.screen(110, 40).join("\n");
        // **One list now, so there is one empty sentence** — and the operator's row is drawn with
        // its author beside it.
        assert!(
            screen.contains("todos") && screen.contains("my own row"),
            "the operator's row is not drawn: {screen}"
        );
        assert!(
            screen.contains("my own row  — you"),
            "the row does not wear its author's tag: {screen}"
        );
    }

    /// The parse, as the pane would draw it with no colour — so a test asserts
    /// the rows and not the escape codes.
    fn todo_plain(body: &str) -> String {
        render_todo_md(body)
            .into_iter()
            .flat_map(|r| {
                let pad = " ".repeat(r.indent);
                let head = match r.mark {
                    Some(m) => format!("{pad}{} {}", m.glyph(), r.text),
                    None => format!("{pad}{}", r.text),
                };
                // The body too, so a test can assert what an unfolded item shows.
                std::iter::once(head)
                    .chain(r.body.into_iter().map(move |l| format!("{pad}    {l}")))
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// **The items are the queue, and they were never drawn.** The pane rendered
    /// one line per heading with counts beside it and stopped. The operator,
    /// looking at `leticl`'s: *"our todo pane doesnt render them — only section
    /// titles and sub todos count"*.
    #[test]
    fn a_heading_rolls_up_its_items_the_way_org_does() {
        let all = todo_plain(
            "# title\n\
             \n\
             ## Phase 0 — repo\n\
             \n\
             - [x] **T1** git init, `.gitignore`.\n\
             - [x] **T2** vendor the deps.\n\
             \n\
             ## Phase 7 — parity\n\
             \n\
             - [x] **S1** the side-by-side diff\n\
             - [~] **S2** the session picker\n\
             - [ ] **S3** the mode card\n\
             \n\
             ## Phase 9 — not started\n\
             \n\
             - [ ] **Z1** nothing yet\n",
        );

        // Every child done makes the parent done — org's own rule for a heading.
        assert!(all.contains("[x] Phase 0 — repo  [2/2]"), "{all}");
        // One started makes it started, and the cookie counts only the finished.
        assert!(all.contains("[~] Phase 7 — parity  [1/3]"), "{all}");
        // None started leaves it open.
        assert!(all.contains("[ ] Phase 9 — not started  [0/1]"), "{all}");

        // And the items themselves, under their heading, in order, with their own
        // marks and without markdown's emphasis noise.
        assert!(all.contains("[x] T1 git init, .gitignore."), "{all}");
        assert!(all.contains("[~] S2 the session picker"), "{all}");
        assert!(all.contains("[ ] S3 the mode card"), "{all}");
        assert!(!all.contains("**"), "the markers are stripped: {all}");
        let (s1, s2) = (all.find("S1").unwrap(), all.find("S2").unwrap());
        assert!(s1 < s2, "file order is kept");
    }

    /// A heading with no checkboxes under it is not done — it is a section
    /// nobody has filled in, and org does not mark those either. This is also
    /// every prose heading in a real TODO.md, which must not be claimed as
    /// finished work.
    #[test]
    fn an_empty_heading_carries_no_box_and_no_cookie() {
        let all = todo_plain(
            "## Dependency graph\n\nT1 -> T3 -> T4\n\n## Phase 0\n\n- [x] **T1** done\n",
        );
        assert!(all.contains("Dependency graph"), "{all}");
        assert!(
            !all.contains("[x] Dependency graph") && !all.contains("[ ] Dependency graph"),
            "an empty section is neither done nor open: {all}"
        );
        assert!(
            !all.contains("Dependency graph  ["),
            "and carries no cookie: {all}"
        );
        assert!(all.contains("[x] Phase 0  [1/1]"), "{all}");
    }

    /// **The head asks for the settings on attach.** The daemon answers
    /// `ClientFrame::Settings` and never pushes the rows, so a head that had not
    /// opened `/mode` or `/config` had none — and the header, which reads the
    /// live `model` row, fell back to the model `Hello` named. The operator, on a
    /// session answered by deepseek: *"restarted the letibot - still qwen"*.
    #[test]
    fn attaching_asks_for_the_settings_so_the_header_is_not_stale() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        assert!(
            a.take_actions().contains(&Action::Settings),
            "attach asks for them"
        );
        // Before the answer, the header falls back to Hello's model — which is
        // what it always did, and is right until something better arrives.
        assert!(a.header_line(200).contains("qwen-3.8-flash-next"));
        a.apply(model_settings("deepseek/deepseek-flash", &["local"]));
        assert!(a.header_line(200).contains("deepseek/deepseek-flash"));
    }

    /// **The money meter.** `micros_usd` was computed by the daemon and read in
    /// exactly one place — the one-shot `--prompt` printer — so a session driven
    /// from a head never saw it. The operator, on a metered conversation: *"still
    /// no money"*. Correct: the meter existed for a surface they were not using.
    #[test]
    fn a_metered_turn_puts_its_cost_on_the_header_and_the_total_accumulates() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        // A free turn lights nothing: free and unpriced are both "no number",
        // and a `$0.0000` on a local session would be noise on every header.
        a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
        a.apply(ServerFrame::Event(env(2, finished_costing("t1", None))));
        assert!(!a.header_line(200).contains('$'), "{}", a.header_line(200));

        // Two metered turns, summed.
        a.apply(ServerFrame::Event(env(3, testing::turn_started("t2"))));
        a.apply(ServerFrame::Event(env(4, finished_costing("t2", Some(33)))));
        a.apply(ServerFrame::Event(env(5, testing::turn_started("t3"))));
        a.apply(ServerFrame::Event(env(
            6,
            finished_costing("t3", Some(12_345)),
        )));
        let h = a.header_line(200);
        assert!(h.contains("$0.0124"), "33 + 12345 micro-USD: {h}");

        // The total is the conversation's, not the head's: switching sessions
        // must not carry one session's bill onto another's header.
        a.apply(hello(
            "s2",
            vec![brief("s", "one", false)],
            Hub::new("s2").snapshot(),
        ));
        assert!(!a.header_line(200).contains('$'), "{}", a.header_line(200));
    }

    fn finished_costing(turn: &str, micros: Option<u64>) -> SessionEvent {
        SessionEvent::TurnFinished {
            turn_id: turn.into(),
            finish_reason: letibot_sessionlog::event::FinishReason::Eos,
            usage: Usage {
                prompt_tokens: 100,
                cached_tokens: 0,
                predicted_tokens: 10,
                cost_micros_usd: micros,
            },
            timings: letibot_sessionlog::event::Timings {
                prompt_ms: 1.0,
                predicted_ms: 1.0,
                wall_ms: 2,
            },
        }
    }

    /// **A pane longer than the terminal was a pane whose tail could not be
    /// read.** Every pane drew `rows.truncate(room)` and the scroll keys were
    /// swallowed while one was open — right about not moving the view
    /// underneath, and it left the pane itself unable to move at all.
    /// `leticl`'s TODO.md renders 98 rows; on a 40-row terminal more than half
    /// of it was unreachable.
    #[test]
    fn a_pane_taller_than_the_screen_scrolls_to_its_end() {
        let dir = std::env::temp_dir().join(format!(
            "letibot-todo-scroll-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("scratch");
        let mut body = String::from("## Phase 0\n\n");
        for i in 0..60 {
            body.push_str(&format!("- [ ] **T{i}** item number {i}\n"));
        }
        std::fs::write(dir.join("TODO.md"), &body).expect("write");

        let mut a = app();
        a.wiring.workspace = dir.display().to_string();
        a.key(Key::CtrlP);
        let top = a.screen(110, 20).join("\n");
        assert!(top.contains("T0 item number 0"), "{top}");
        assert!(
            !top.contains("T59 item number 59"),
            "the tail is off-screen: {top}"
        );

        // PageDown reaches it. Enough presses to pass the end — the clamp is
        // what stops it, and scrolling past into blank rows would be its own bug.
        for _ in 0..20 {
            a.key(Key::PageDown);
            a.screen(110, 20);
        }
        let end = a.screen(110, 20).join("\n");
        assert!(end.contains("T59 item number 59"), "{end}");
        assert!(!end.contains("T0 item number 0"), "{end}");
        // The last screenful, not past it: the final row is still drawn.
        assert!(
            a.pane_scroll == a.pane_len.saturating_sub(a.pane_room),
            "clamped to the last screenful: {} of {}/{}",
            a.pane_scroll,
            a.pane_len,
            a.pane_room
        );

        // And back up.
        for _ in 0..20 {
            a.key(Key::PageUp);
            a.screen(110, 20);
        }
        assert_eq!(a.pane_scroll, 0);
        assert!(a.screen(110, 20).join("\n").contains("T0 item number 0"));

        // A reopened pane starts at the top rather than where it was left.
        a.key(Key::PageDown);
        a.screen(110, 20);
        a.key(Key::Esc);
        a.key(Key::CtrlP);
        assert_eq!(a.pane_scroll, 0);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The cursor keeps itself on screen: an arrow that walks the selection out
    /// of the window reads as a key that does nothing.
    #[test]
    fn the_cursor_scrolls_itself_into_view() {
        let dir = std::env::temp_dir().join(format!(
            "letibot-todo-cursor-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("scratch");
        let mut body = String::from("## Phase 0\n\n");
        for i in 0..40 {
            body.push_str(&format!("- [ ] **T{i}** item {i}\n"));
        }
        std::fs::write(dir.join("TODO.md"), &body).expect("write");
        let mut a = app();
        a.wiring.workspace = dir.display().to_string();
        a.key(Key::CtrlP);
        a.screen(110, 20);

        for _ in 0..30 {
            a.key(Key::Down);
        }
        let screen = a.screen(110, 20).join("\n");
        assert!(screen.contains("▸"), "the cursor is on screen: {screen}");
        assert!(a.pane_scroll > 0, "which took scrolling: {}", a.pane_scroll);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// **Tab unfolds, like enter.** The operator, after using the pane: *"i also
    /// feel like I want Tab to expand the todo row"*. It completes a `/command`
    /// while one is being typed, and the composer is empty here — the same
    /// condition enter already carried.
    #[test]
    fn tab_unfolds_an_item_and_still_completes_a_command() {
        let dir = std::env::temp_dir().join(format!(
            "letibot-todo-tab-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("scratch");
        std::fs::write(
            dir.join("TODO.md"),
            concat!(
                "## Phase 0\n",
                "\n",
                "- [ ] **T1** head\n",
                "  the body line\n"
            ),
        )
        .expect("write");
        let mut a = app();
        a.wiring.workspace = dir.display().to_string();
        a.key(Key::CtrlP);
        assert!(!a.screen(110, 30).join("\n").contains("the body line"));
        // **The cursor starts on the ADD CONTROL**, which is the head of `todos_stops` and
        // leticl's own starting position — so one Down is what puts it on the first repo item. The
        // row under the cursor is the row Enter and Tab act on, which is the whole point of one
        // enumeration; before this change the cursor had nowhere else to be and these keys were
        // reading a different list from the one the pane drew.
        a.key(Key::Down);
        a.key(Key::Tab);
        assert!(
            a.screen(110, 30).join("\n").contains("the body line"),
            "tab unfolds"
        );
        a.key(Key::Tab);
        assert!(
            !a.screen(110, 30).join("\n").contains("the body line"),
            "and folds"
        );

        // With something typed, Tab is still the completion key: the pane does
        // not get to eat it just because it is open.
        for c in "/mod".chars() {
            a.key(Key::Char(c));
        }
        a.key(Key::Tab);
        assert!(
            a.editor.text().starts_with("/mode"),
            "completion still works: {:?}",
            a.editor.text()
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// **An item's detail is under it in the file and was thrown away.**
    ///
    /// `- [x] **T2** vendor yason …, pinned in` continues on the next line with
    /// the commits it pins; the pane showed the first line and stopped, so the
    /// item trailed off mid-sentence. The operator: *"if a todo has some
    /// associated text? should i be able to expand it somehow?"*
    #[test]
    fn an_items_continuation_lines_are_kept_and_unfold_on_enter() {
        // Written with explicit newlines rather than `\`-continuations: that
        // escape eats the leading whitespace of the next line, which is exactly
        // the indentation this test is about.
        let body = concat!(
            "## Phase 0\n",
            "\n",
            "- [x] **T1** vendor the deps, pinned in\n",
            "  `scripts/bootstrap.sh` (yason `0c84b29`).\n",
            "  Deps: none.\n",
            "- [ ] **T2** no body at all\n",
            "\n",
            "Prose after a blank line belongs to nobody.\n",
        );
        // The parse keeps it.
        let all = todo_plain(body);
        assert!(
            all.contains("scripts/bootstrap.sh (yason 0c84b29)."),
            "{all}"
        );
        assert!(all.contains("Deps: none."), "{all}");
        assert!(
            !all.contains("Prose after a blank"),
            "a blank line closes the item: {all}"
        );

        let dir = std::env::temp_dir().join(format!(
            "letibot-todo-body-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("scratch");
        std::fs::write(dir.join("TODO.md"), body).expect("write");
        let mut a = app();
        a.wiring.workspace = dir.display().to_string();
        a.key(Key::CtrlP);

        // Folded: the first line, and a mark that there is more. T2 has no body
        // and so carries no mark — `···` means "there is more", not "this is an
        // item".
        let screen = a.screen(110, 40).join("\n");
        assert!(
            screen.contains("T1 vendor the deps, pinned in ···"),
            "{screen}"
        );
        assert!(screen.contains("T2 no body at all"), "{screen}");
        assert!(!screen.contains("T2 no body at all ···"), "{screen}");
        assert!(
            !screen.contains("bootstrap.sh"),
            "folded hides it: {screen}"
        );

        // **The cursor starts on the `[+]` control**, which is the head of the one enumeration —
        // leticl's `todos-stops` — and NOT on the first item. It was on the first item while the
        // cursor's position came from an index into the repo's rows; the operator's two reports,
        // *"arrows dont go here"* and *"mouse doesnt click"*, were both that one defect, because
        // the pane drew the mark from one list and the keys acted on another. There is one list.
        let screen = a.screen(110, 40).join("\n");
        let on = |s: &str, what: &str| {
            s.lines()
                .find(|l| l.contains('▸'))
                .is_some_and(|l| l.contains(what))
        };
        assert!(on(&screen, "[+] add todo item"), "starts on the control: {screen}");
        // The model's rows and your own are not stops either, so the arrows never park on a row
        // where no key acts — the same reason the repo's headings are skipped.
        assert!(
            !screen.contains("▸ T1"),
            "the cursor is not on an item yet: {screen}"
        );

        // One Down is what reaches the first item, and Enter unfolds it.
        a.key(Key::Down);
        let screen = a.screen(110, 40).join("\n");
        assert!(on(&screen, "T1 vendor the deps"), "down reached T1: {screen}");
        assert_eq!(a.key(Key::Enter), None);
        let screen = a.screen(110, 40).join("\n");
        assert!(on(&screen, "T1 vendor the deps"), "Enter does not move the cursor: {screen}");
        assert!(
            screen.contains("scripts/bootstrap.sh (yason 0c84b29)."),
            "{screen}"
        );
        assert!(screen.contains("Deps: none."), "{screen}");
        assert!(
            !screen.contains("pinned in ···"),
            "unfolded drops the mark: {screen}"
        );

        // Enter again folds it; an arrow moves on and folds what it leaves.
        a.key(Key::Enter);
        assert!(!a.screen(110, 40).join("\n").contains("bootstrap.sh"));
        a.key(Key::Enter);
        a.key(Key::Down);
        let screen = a.screen(110, 40).join("\n");
        assert!(
            !screen.contains("bootstrap.sh"),
            "moving off an item folds it: {screen}"
        );
        assert!(
            on(&screen, "T2 no body at all"),
            "the arrow moved on to T2: {screen}"
        );

        // Down past the last item wraps — and the head of the list is the `[+]` control, because
        // that is where the enumeration starts. Up from the control wraps to the LAST item, so it
        // never lands on the `## Phase 0` heading, which has nothing to unfold.
        a.key(Key::Down);
        let screen = a.screen(110, 40).join("\n");
        assert!(on(&screen, "[+] add todo item"), "wrapped to the control: {screen}");
        a.key(Key::Up);
        let screen = a.screen(110, 40).join("\n");
        assert!(
            on(&screen, "T2 no body at all"),
            "up from the control wraps to the last ITEM, not to the heading: {screen}"
        );
        assert_eq!(
            a.repo_sel, 2,
            "and the repo cursor follows, so the two cannot disagree"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// **Both halves of the pane speak one vocabulary.** The operator, on seeing
    /// the items drawn: *"colors?"*. They were not painted at all — neither the
    /// model's list nor the repo's — while the jobs pane two keys away had been
    /// painting the same three states green and yellow all along.
    #[test]
    fn a_todo_is_painted_by_its_state_in_both_halves() {
        let dir = std::env::temp_dir().join(format!(
            "letibot-todo-colour-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("scratch");
        std::fs::write(
            dir.join("TODO.md"),
            "## Phase 0\n\n- [x] **T1** done\n- [~] **T2** doing\n- [ ] **T3** open\n",
        )
        .expect("write");

        let mut a = App::new(RenderConfig {
            color: true,
            ..plain_cfg(110)
        });
        a.wiring.workspace = dir.display().to_string();
        a.apply(ServerFrame::Event(env(
            1,
            SessionEvent::TodosUpdated {
                todos: vec![
                    letibot_sessionlog::event::TodoEntry {
                        by: letibot_sessionlog::event::TodoBy::Model,
                        content: "seated".into(),
                        status: letibot_sessionlog::event::TodoStatus::Completed,
                    },
                    letibot_sessionlog::event::TodoEntry {
                        // A model's plan, which is also the field's serde default.
                        by: letibot_sessionlog::event::TodoBy::Model,
                        content: "seating".into(),
                        status: letibot_sessionlog::event::TodoStatus::InProgress,
                    },
                ],
            },
        )));
        a.key(Key::CtrlP);
        let screen = a.screen(110, 40).join("\n");

        // The model's half.
        assert!(
            screen.contains(&format!("{}[x]{} seated", sgr::GREEN, sgr::RESET)),
            "{screen:?}"
        );
        assert!(
            screen.contains(&format!("{}[~]{} seating", sgr::YELLOW, sgr::RESET)),
            "{screen:?}"
        );
        // The repo's half, painted the same way — including the heading, which
        // carries the rolled-up state and so carries its colour.
        assert!(
            screen.contains(&format!("{}[~]{} Phase 0", sgr::YELLOW, sgr::RESET)),
            "{screen:?}"
        );
        assert!(
            screen.contains(&format!("{}[x]{} T1 done", sgr::GREEN, sgr::RESET)),
            "{screen:?}"
        );
        // An open item is left alone: it is the default and the majority of any
        // list, and colouring the majority spends the signal the other two carry.
        assert!(screen.contains("[ ] T3 open"), "{screen:?}");
        assert!(
            !screen.contains(&format!("{}[ ]", sgr::GREEN))
                && !screen.contains(&format!("{}[ ]", sgr::YELLOW)),
            "{screen:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// **The file is edited while the pane is open**, which is the one case an
    /// open-time read cannot see. The operator: *"since the file can be updated,
    /// dont cache it i guess or do a watcher with a nice syscall"*. One `stat`
    /// per draw, not a watcher thread.
    #[test]
    fn the_pane_notices_the_file_changing_under_it() {
        let dir = std::env::temp_dir().join(format!(
            "letibot-todo-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).expect("scratch");
        let path = dir.join("TODO.md");
        std::fs::write(&path, "## Phase 0\n\n- [ ] **T1** open\n").expect("write");

        let mut a = app();
        a.wiring.workspace = dir.display().to_string();
        a.key(Key::CtrlP);
        assert!(a.screen(110, 40).join("\n").contains("[ ] Phase 0  [0/1]"));

        // The operator ticks it off in their editor, with the pane still up.
        // The length changes, so a second-granularity mtime cannot hide it.
        std::fs::write(&path, "## Phase 0\n\n- [x] **T1** open, now done\n").expect("write");
        let screen = a.screen(110, 40).join("\n");
        assert!(
            screen.contains("[x] Phase 0  [1/1]"),
            "the next draw sees it: {screen}"
        );

        // And an unchanged file is not re-read: the stat is the point of the
        // cache, not a decoration on it.
        let before = a.repo_todos_at;
        a.screen(110, 40);
        assert_eq!(a.repo_todos_at, before);

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// `###` is a subsection in org's outline and in markdown's, so its items
    /// belong to it rather than to the `##` above.
    #[test]
    fn a_subsection_owns_its_own_items() {
        let all = todo_plain("## Phase 7\n\n- [x] **A** one\n\n### Strand B\n\n- [ ] **B1** two\n");
        assert!(all.contains("[x] Phase 7  [1/1]"), "{all}");
        assert!(all.contains("[ ] Strand B  [0/1]"), "{all}");
    }

    /// **The prompt is a control, not a spelling test.**
    ///
    /// Up and Down walk the ladder and Enter takes the highlighted one — the operator
    /// never types a word they can get wrong. Reported twice as *"it wasn't a choice
    /// but something I have to type (and mistype) myself"* before it was built.
    #[test]
    fn a_decision_is_answered_with_the_arrows_and_enter() {
        let mut a = app();
        a.apply(ServerFrame::Event(env(1, testing::requested("r1", "rm"))));
        let opts: Vec<String> = a.open_decisions()[0]
            .options
            .iter()
            .map(|o| o.option_id.clone())
            .collect();
        assert!(opts.len() >= 2, "need a ladder to walk: {opts:?}");

        // Enter with nothing typed takes the FIRST option, because a fresh question
        // starts at the top of its own ladder.
        assert_eq!(
            a.key(Key::Enter),
            Some(Action::Answer {
                req_id: "r1".into(),
                option_id: opts[0].clone(),
                pattern: None,
                note: None
            })
        );

        // Down moves one, and the answer follows the marker rather than the order the
        // options happen to arrive in.
        let mut b = app();
        b.apply(ServerFrame::Event(env(1, testing::requested("r2", "rm"))));
        assert_eq!(b.key(Key::Down), None, "moving is not answering");
        assert_eq!(
            b.key(Key::Enter),
            Some(Action::Answer {
                req_id: "r2".into(),
                option_id: opts[1].clone(),
                pattern: None,
                note: None
            })
        );

        // Up from the top wraps to the bottom rather than sticking, so the last option
        // — which is usually the one that denies — is one keypress away.
        let mut c = app();
        c.apply(ServerFrame::Event(env(1, testing::requested("r3", "rm"))));
        assert_eq!(c.key(Key::Up), None);
        assert_eq!(
            c.key(Key::Enter),
            Some(Action::Answer {
                req_id: "r3".into(),
                option_id: opts[opts.len() - 1].clone(),
                pattern: None,
                note: None
            })
        );
    }

    /// The arrows belong to the decision only while the composer is empty.
    ///
    /// A half-typed line still edits, so nothing was taken away from the person
    /// who prefers typing — including `/command`, which shares Enter. Enter does
    /// NOT send the line while an ask is open: the ask arrived while the line
    /// was being typed, and Enter on a card means "answer this" (the operator,
    /// 2026-09-17: *"when i hit enter my unfinished prompt gets sent first"*).
    /// The line is held and the next Enter, with the ask settled, sends it.
    #[test]
    fn enter_on_an_ask_answers_it_and_holds_the_half_typed_line() {
        let mut a = app();
        a.apply(ServerFrame::Event(env(1, testing::requested("r1", "rm"))));
        typed(&mut a, "some prose");
        // **The arrows reach the ladder even mid-line, and the line is untouched.**
        //
        // They used to belong to the composer here, so that "the ladder cursor does
        // not move under the operator's feet" — which sounded right and meant that
        // the only way to choose an option while typing was to empty the composer
        // first. The operator, 2026-09-20: *"until i press down arrow I wont get
        // into the permissions menu, by which time my prompt is erased and gone"*.
        a.key(Key::Down);
        assert_eq!(a.sel, 1, "the ladder moved");
        assert_eq!(a.input(), "some prose", "and the line is still there");
        a.key(Key::Up);
        assert_eq!(a.sel, 0);
        assert_eq!(a.input(), "some prose");
        // Enter answers the ask with the marked row and holds the line.
        assert_eq!(
            a.key(Key::Enter),
            Some(Action::Answer {
                req_id: "r1".into(),
                option_id: "allow".into(),
                pattern: None,
                note: None
            })
        );
        assert_eq!(a.input(), "some prose", "the words are held, not sent");
        assert!(a.pending_prompts.is_empty(), "nothing was sent");
        // With the ask settled, the next Enter sends the held line.
        a.apply(ServerFrame::Event(env(2, testing::answered("r1", "allow"))));
        assert_eq!(a.key(Key::Enter), Some(Action::Prompt("some prose".into())));
    }

    #[test]
    fn an_open_decision_is_answered_by_typing_the_option() {
        let mut a = app();
        a.apply(ServerFrame::Event(env(1, testing::requested("r1", "rm"))));
        typed(&mut a, "deny");
        assert_eq!(
            a.key(Key::Enter),
            Some(Action::Answer {
                req_id: "r1".into(),
                option_id: "deny".into(),
                pattern: None,
                note: None
            })
        );
        assert_eq!(a.input(), "", "the typed id is consumed, not held");
    }

    #[test]
    fn ctrl_c_clears_the_composer_and_only_a_double_tap_asks() {
        // The old rule quit an idle head on one press and interrupted a running
        // one, so there was no way to abandon a half-typed prompt and a stray
        // Ctrl+C killed the head. opencode's rule, via `letibot_ui::editor`.
        //
        // The double tap now opens the quit card rather than leaving outright —
        // see `the_quit_card_offers_both_exits_and_defaults_to_the_cheap_one`.
        let mut a = app();
        a.clock(1_000);
        typed(&mut a, "half a question I am still");
        assert_eq!(a.key(Key::CtrlC), None, "it clears, it does not quit");
        assert_eq!(a.input(), "");
        assert_eq!(a.key(Key::CtrlC), None, "one press on an empty composer");
        assert_eq!(
            a.key(Key::CtrlC),
            None,
            "the second opens the card, it does not leave"
        );
        assert!(a.quit_card, "the card is up");
    }

    /// **Ctrl+C Ctrl+C asks which exit.** The operator, 2026-09-17: *"when i do
    /// CcCc i should be asked if I want to exit letibot or letibot and
    /// harnessd"*.
    ///
    /// The card defaults to the cheap answer, because the other one takes the
    /// daemon's KV with it and a cold prefill of a long session is minutes on
    /// this box — a default that costs that much is a default that has answered
    /// for the operator.
    /// **A row number is focus and enter, on every card that draws one.** The
    /// operator, 2026-09-17: *"it shows numbered lists anyway so me pressing row
    /// number should constitute focus and enter"*.
    ///
    /// One rule, three cards, and the same guard on each: the composer must be
    /// empty, so a line already being typed keeps its digits.
    /// **The door's verbs are typed with hyphens** — R34.
    ///
    /// The operator: *"lets change /web_search to /web-search - no shift needed."* The door's
    /// names were the only underscored verbs in either registry, and they were underscored
    /// because they are spelled straight from the TOOL names. Right for the wire, wrong for a
    /// keyboard.
    ///
    /// Three assertions, and they are the three clauses of the requirement: the hyphen form is
    /// what is OFFERED, the underscore form is ACCEPTED, and **the wire still carries the
    /// tool's own name** — this is a textual transform and not knowledge about the tool.
    #[test]
    fn a_door_verb_is_typed_with_hyphens() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        a.apply(door_row("web_search", "query", "text"));

        // **Offered hyphenated.** Tab from `/web-` reaches it.
        typed(&mut a, "/web-");
        a.key(Key::Tab);
        assert_eq!(a.input(), "/web-search");

        // **And the underscore form is accepted rather than refused** — an operator who
        // types what the daemon calls it should not be told they are wrong.
        assert_eq!(
            a.command("web-search blabla"),
            Some(Action::HeadRun {
                name: "web_search".into(),
                arguments: r#"{"query":"blabla"}"#.into(),
            }),
            "the hyphen form sends the TOOL's name"
        );
        assert_eq!(
            a.command("web_search blabla"),
            Some(Action::HeadRun {
                name: "web_search".into(),
                arguments: r#"{"query":"blabla"}"#.into(),
            }),
            "and so does the underscore form: `/web-search` and `/web_search` are one verb"
        );
        // Case is a hand's, not a meaning's.
        assert_eq!(
            a.command("Web-Search blabla"),
            Some(Action::HeadRun {
                name: "web_search".into(),
                arguments: r#"{"query":"blabla"}"#.into(),
            })
        );
    }

    /// **The head holds no schema: the arguments come off the row.**
    ///
    /// Four facts, and each is a different way for the head to be right without knowing what
    /// the tool is: the field the line goes into, the defaults that travel with it, the
    /// no-bare-form refusal in the daemon's own words, and the JSON form kept for a tool with
    /// several arguments.
    #[test]
    fn the_bare_form_is_built_from_the_row_and_nothing_else() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        a.apply(door_row("read", "path", "path"));
        assert_eq!(
            a.command("read crates/tui/src/app.rs"),
            Some(Action::HeadRun {
                name: "read".into(),
                arguments: r#"{"path":"crates/tui/src/app.rs"}"#.into(),
            })
        );

        // **A default travels with the line**, so a bare form sends what a model's minimal
        // call would have sent.
        let mut b = app();
        b.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        let mut row = door_row("web_fetch", "url", "url");
        if let ServerFrame::Settings { rows } = &mut row {
            rows[0].tools[0]
                .defaults
                .insert("format".into(), "markdown".into());
        }
        b.apply(row);
        // **Compared as a VALUE, not as a string.** Key order in a JSON object is not a fact
        // about the call, and an assertion on it would fail the day the map's iteration
        // changes while the call stayed the same.
        let Some(Action::HeadRun { name, arguments }) =
            b.command("web-fetch http://example.invalid")
        else {
            panic!("the bare form did not produce a door call");
        };
        assert_eq!(name, "web_fetch");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&arguments).expect("an object"),
            serde_json::json!({"url": "http://example.invalid", "format": "markdown"}),
            "the field the line went into, and the default that travelled with it"
        );

        // **No bare form: the daemon's own sentence, not the head's guess.**
        //
        // Called on the function rather than through `command`, and the reason is worth
        // stating: the door's three tools ALL have a single required field today, so this
        // branch is unreachable through a real row — it exists for an allowlist entry with two
        // required fields, and the sentence it returns is the daemon's `why_json`. A test that
        // could not reach it would be no test at all.
        let mut c = app();
        c.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        let two_fields = letibot_sessionlog::HeadRunTool {
            name: "pair".into(),
            field: String::new(),
            kind: String::new(),
            defaults: Default::default(),
            why_json: "`pair` needs 2 fields (a, b)".into(),
        };
        let why = c
            .head_run_call(&two_fields, "a b")
            .expect_err("a tool with no bare form is refused");
        assert_eq!(
            why, "`pair` needs 2 fields (a, b)",
            "the daemon's own sentence"
        );
        // And a bare verb with nothing after it is refused by name, with the field named —
        // a call to a tool that needs a query, with no query, is a call nobody meant.
        let read = letibot_sessionlog::HeadRunTool {
            name: "read".into(),
            field: "path".into(),
            kind: "path".into(),
            defaults: Default::default(),
            why_json: String::new(),
        };
        let why = c.head_run_call(&read, "   ").expect_err("no path, no call");
        assert!(
            why.contains("/read WHAT") && why.contains("`path`"),
            "{why}"
        );
        assert!(why.contains("path"), "the kind is named: {why}");

        // **And the JSON form stays**, which is what a tool with several arguments needs.
        let Some(Action::HeadRun { arguments, .. }) = a.command(r#"read {"path":"x","limit":3}"#)
        else {
            panic!("the JSON form was not accepted");
        };
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&arguments).expect("an object"),
            serde_json::json!({"path": "x", "limit": 3}),
            "the JSON form goes through untouched — checked for BEING json and nothing else"
        );
        // **The JSON form is entered by the brace, and only by it.** A line with spaces is
        // ONE bare argument, which is how a path with a space in it works; a line that opens
        // with `{` is the operator asking for the JSON form and is parsed as one.
        let Some(Action::HeadRun { arguments, .. }) = a.command("read x y") else {
            panic!("a line with spaces is one bare path");
        };
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&arguments).unwrap(),
            serde_json::json!({"path": "x y"})
        );
        assert_eq!(
            a.command("read {not json"),
            None,
            "an opening brace promises JSON; a malformed one is refused, not read as a path"
        );
        assert!(
            a.notice.as_deref().is_some_and(|n| n.contains("read")),
            "and the refusal names the verb: {:?}",
            a.notice
        );
        // **And the object is passed through unexamined** — checked for BEING json and for
        // nothing else, which is R24's own rule kept: the head does not know `path` is
        // required, so it does not pretend to, and the tool's own refusal is the one that
        // reaches the operator.
        let Some(Action::HeadRun { arguments, .. }) = a.command(r#"read {"limit":3}"#) else {
            panic!("an object is accepted whatever is in it");
        };
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&arguments).unwrap(),
            serde_json::json!({"limit": 3})
        );
    }

    /// **The door's list is the daemon's allowlist, not the row.** A row naming a tool the
    /// daemon does not admit is not a door verb — the row describes what is admitted, and a
    /// head that trusted a row over the list would be offering a call the daemon refuses.
    ///
    /// This is the failure that taught me: the first version of the test above used a
    /// two-required-field tool called `pair` and expected the door to refuse it. It did not —
    /// `pair` is not in `HEAD_RUN_TOOLS`, so it fell through to the daemon as an ordinary
    /// unknown verb, which is exactly right.
    #[test]
    fn a_row_naming_a_tool_outside_the_allowlist_is_not_a_door_verb() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        a.apply(door_row("bash", "command", "text"));
        assert!(
            matches!(a.command("bash rm -rf /"), Some(Action::Slash { .. })),
            "the door does not admit `bash` and the row cannot make it"
        );
    }

    /// **A verb the head has no tool for is not swallowed by the door.** The door arm runs
    /// first in `command`, so a name it does not match must fall through to everything else
    /// — otherwise every verb in the registry would be refused by a door that never heard of
    /// it.
    #[test]
    fn a_verb_that_is_not_a_door_tool_falls_through() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        a.apply(door_row("read", "path", "path"));
        // A daemon verb still goes to the daemon.
        assert!(matches!(
            a.command("gate recent"),
            Some(Action::Slash { .. })
        ));
        // And a head verb still does what it did.
        assert_eq!(a.command("t"), None);
        assert!(a.tools.is_open());
        // A door name with no row is not a door: nothing was published, so nothing is
        // matched, and it goes to the daemon like any other unknown word.
        assert!(matches!(
            a.command("web-search blabla"),
            Some(Action::Slash { .. })
        ));
    }

    /// The short spellings `command()` keeps taking and the table deliberately does not
    /// carry: offering both spellings doubles the list to teach the same actions.
    const HEAD_COMMAND_ALIASES: &[&str] = &["?", "h", "q", "r", "s", "t", "v", "i"];

    /// **The completion table and the dispatcher are not two lists that agree by
    /// maintenance** (R32).
    ///
    /// In Rust a `match` is not reflectable, so of the two mechanisms the requirement
    /// allows — one derived from the other, or a test that fails when they diverge — this is
    /// the second. It reads the source of [`App::command`] and names every verb in it, so an
    /// arm added without a row in [`SLASH_COMMANDS`] fails here rather than becoming a verb
    /// nobody is ever offered.
    ///
    /// **The finding it pins, measured on this tree 2026-09-23**
    /// (`docs/evidence/slash-completion-2026-09-23.py`): the table offered 27 verbs and the
    /// dispatcher acted on 38, and the gap was not one oversight but the shape — a registry
    /// that exists for one purpose read as the answer to a different question.
    ///
    /// `HEAD_COMMAND_ALIASES` are excluded on purpose: the table's own comment says offering
    /// both spellings doubles the list to teach the same actions, and `command()` keeps
    /// taking them.
    #[test]
    fn every_verb_the_dispatcher_acts_on_is_offered_by_tab() {
        // The dispatcher's own source, so this cannot drift from the code it is about.
        const SRC: &str = include_str!("app.rs");
        let start = SRC
            .find("    fn command(&mut self, cmd: &str) -> Option<Action> {")
            .expect("the dispatcher");
        let mut depth = 0usize;
        let mut end = start;
        for (i, c) in SRC[start..].char_indices() {
            match c {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        end = start + i;
                        break;
                    }
                }
                _ => {}
            }
        }
        let body = &SRC[start..end];

        // **Plain string surgery, no regex**: this crate has no regex dependency and
        // adding one to a test would be a dependency for the test's convenience.
        let mut acted: Vec<String> = Vec::new();
        let quoted = |hay: &str| -> Vec<String> {
            hay.split('"')
                .skip(1)
                .step_by(2)
                .map(str::to_string)
                .collect()
        };
        // `verb_arg(cmd, "x")` — the leading-position verbs that take arguments.
        for (i, _) in body.match_indices("verb_arg(cmd, \"") {
            let rest = &body[i + "verb_arg(cmd, \"".len()..];
            if let Some(q) = rest.find('"') {
                acted.push(rest[..q].to_string());
            }
        }
        // `matches!(cmd, "a" | "b")`.
        for (i, _) in body.match_indices("matches!(cmd, ") {
            let rest = &body[i + "matches!(cmd, ".len()..];
            let close = rest.find(')').expect("a matches! has a close");
            acted.extend(quoted(&rest[..close]));
        }
        // `cmd.strip_prefix("switch ")`.
        for (i, _) in body.match_indices("cmd.strip_prefix(\"") {
            let rest = &body[i + "cmd.strip_prefix(\"".len()..];
            if let Some(q) = rest.find('"') {
                acted.push(rest[..q].trim().to_string());
            }
        }
        // The `match cmd` arms: a run of `"a" | "b"` before a `=>`, **at the match's own
        // depth**. Two guards, and the second is the one that matters: a string literal
        // inside an arm's BODY also begins a trimmed line with a quote, and a first draft of
        // this test reported seven verbs including `self.say`'s prose — a check that greps
        // for nearly the right thing reads exactly like a check that greps for the right
        // one, which is this document's oldest note.
        let mi = body.find("        match cmd {").expect("the match");
        let mut d = 0i32;
        for line in body[mi..].split('\n') {
            let t = line.trim();
            if d == 1 && t.starts_with('"') && t.contains("=>") {
                let head = t.split("=>").next().unwrap_or("");
                acted.extend(quoted(head));
            }
            d += line.matches('{').count() as i32 - line.matches('}').count() as i32;
        }
        assert!(
            acted.len() > 20,
            "the extraction found {} verbs",
            acted.len()
        );

        let offered: Vec<&str> = SLASH_COMMANDS.iter().map(|(n, _)| *n).collect();
        let mut missing: Vec<&String> = acted
            .iter()
            .filter(|v| {
                !offered.contains(&v.as_str())
                    && !HEAD_COMMAND_ALIASES.contains(&v.as_str())
                    // A `reseat` modifier is the same verb: the table carries the base and
                    // the one modifier worth a line of its own.
                    && !v.starts_with("reseat")
            })
            .collect();
        missing.sort();
        missing.dedup();
        assert!(
            missing.is_empty(),
            "/help and Tab cannot offer a verb the head acts on: {missing:?}\n\
             Add a row to SLASH_COMMANDS (or to HEAD_COMMAND_ALIASES if it is a spelling of \
             another verb). This is the gap `slash-completion-2026-09-23.py` measured."
        );
    }

    /// **The daemon's verbs are not this head's to enumerate** (R32), and the list it draws
    /// comes from the row.
    ///
    /// The measured defect, in one assertion: `/gate`, `/flowy`, `/job`, `/login` and
    /// `/supervise` all work — they are forwarded — and none was offered, because the head
    /// completed from a table that had never heard of them. With the row they are offered;
    /// without it the head offers its own verbs and **says nothing about the rest**, which
    /// is a daemon older than this one and not a guess.
    #[test]
    fn the_daemons_verbs_come_from_its_row_and_are_not_guessed_at() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        // No row yet: only this head's own verbs, and every one of them is dispatched.
        assert!(a.daemon_verbs().is_empty());
        let own = a.command_names();
        assert!(own.iter().any(|(n, _)| n == "compact"), "{own:?}");
        assert!(
            !own.iter().any(|(n, _)| n == "gate"),
            "a verb the daemon has not published must not be invented: {own:?}"
        );

        // Now the daemon answers, and its verbs join the list.
        a.apply(ServerFrame::Settings {
            rows: vec![letibot_sessionlog::protocol::SettingRow {
                key: letibot_sessionlog::protocol::DAEMON_VERBS_KEY.into(),
                value: "flowy,gate,job,login,supervise,tools".into(),
                source: "default".into(),
                editable: String::new(),
                choices: Vec::new(),
                tools: Vec::new(),
            }],
        });
        let all = a.command_names();
        for v in ["flowy", "gate", "job", "login", "supervise"] {
            assert!(
                all.iter().any(|(n, _)| n == v),
                "`/{v}` works and was not offered: {all:?}"
            );
        }
        // **Once each.** `/tools` is in this head's table too, and a list that named it
        // twice would teach it as two verbs.
        let tools = all.iter().filter(|(n, _)| n == "tools").count();
        assert_eq!(tools, 1, "{all:?}");
        // And the head's own hint survives the join.
        let (_, hint) = all.iter().find(|(n, _)| n == "tools").unwrap();
        assert!(!hint.is_empty(), "the head's own row keeps its sentence");

        // Tab now walks the joined list: `/ga` reaches the daemon's `gate`.
        typed(&mut a, "/ga");
        a.key(Key::Tab);
        assert_eq!(a.input(), "/gate");
    }

    /// **A verb the head will refuse is not offered** — R29 pointed the other way, and the
    /// reason the joined list is built from the two OWNERS rather than from anything a
    /// person could type (`/bash`, `/write`): neither half will act on those, and a
    /// completion that suggests one is a remedy that does not work.
    #[test]
    fn completion_offers_nothing_neither_half_will_act_on() {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        a.apply(ServerFrame::Settings {
            rows: vec![letibot_sessionlog::protocol::SettingRow {
                key: letibot_sessionlog::protocol::DAEMON_VERBS_KEY.into(),
                value: "gate,job".into(),
                source: "default".into(),
                editable: String::new(),
                choices: Vec::new(),
                tools: Vec::new(),
            }],
        });
        let all: Vec<String> = a.command_names().into_iter().map(|(n, _)| n).collect();
        for invented in ["bash", "write", "sh", "exec"] {
            assert!(
                !all.iter().any(|n| n == invented),
                "`/{invented}` is offered and neither half acts on it"
            );
        }
    }

    #[test]
    fn a_row_number_answers_the_ask_the_mode_card_and_the_quit_card() {
        // The permission ask.
        let mut a = app();
        a.apply(ServerFrame::Event(env(
            1,
            testing::requested("r1", "`bash` wants exec access"),
        )));
        assert_eq!(
            a.key(Key::Char('2')),
            Some(Action::Answer {
                req_id: "r1".into(),
                option_id: "deny".into(),
                pattern: None,
                note: None
            }),
            "row 2 of the ask is `deny`"
        );

        // The quit card.
        let mut b = app();
        b.clock(1_000);
        b.key(Key::CtrlC);
        b.key(Key::CtrlC);
        assert_eq!(b.key(Key::Char('2')), Some(Action::StopDaemon));

        // Out of range does nothing — it is not an answer and not a keystroke
        // the card invents a meaning for.
        let mut c = app();
        c.clock(1_000);
        c.key(Key::CtrlC);
        c.key(Key::CtrlC);
        assert_eq!(c.key(Key::Char('7')), None, "there is no row 7");
        assert!(c.quit_card, "and the card is still up");
    }

    /// A digit typed into a line that has already started is part of the line,
    /// not an answer — the same empty-composer guard the arrows have.
    #[test]
    fn a_digit_inside_a_half_typed_line_is_not_an_answer() {
        let mut a = app();
        a.apply(ServerFrame::Event(env(
            1,
            testing::requested("r1", "`bash` wants exec access"),
        )));
        typed(&mut a, "give me ");
        assert_eq!(a.key(Key::Char('2')), None, "it went into the line");
        assert_eq!(a.input(), "give me 2");
    }

    #[test]
    fn the_quit_card_offers_both_exits_and_defaults_to_the_cheap_one() {
        let mut a = app();
        a.clock(1_000);
        a.key(Key::CtrlC);
        assert_eq!(a.key(Key::CtrlC), None);
        assert!(a.quit_card);

        let screen = a.screen(100, 24).join("\n");
        assert!(screen.contains("leave this head"), "{screen}");
        assert!(screen.contains("leave and stop the daemon"), "{screen}");
        // The consequence is ON the row, not in a footnote: the two answers are
        // not alike and the card must not make them look it.
        assert!(screen.contains("prefills cold"), "{screen}");
        // And the footer names the keys this card actually takes — it used to
        // say "ctrl+c again to exit", which a third press no longer does.
        assert!(screen.contains("esc stays"), "{screen}");
        assert!(!screen.contains("ctrl+c again to exit"), "{screen}");

        // Enter on an untouched card takes the smaller exit.
        assert_eq!(a.key(Key::Enter), Some(Action::Quit));
    }

    #[test]
    fn the_quit_card_can_stop_the_daemon_and_can_be_taken_back() {
        let mut a = app();
        a.clock(1_000);
        a.key(Key::CtrlC);
        a.key(Key::CtrlC);
        a.key(Key::Down);
        assert_eq!(
            a.key(Key::Enter),
            Some(Action::StopDaemon),
            "the second row"
        );

        // By number, without moving the cursor.
        let mut b = app();
        b.clock(1_000);
        b.key(Key::CtrlC);
        b.key(Key::CtrlC);
        assert_eq!(b.key(Key::Char('2')), Some(Action::StopDaemon));

        // **Esc takes it back.** A card opened by a habit keystroke has to have
        // an answer that is not an exit.
        let mut c = app();
        c.clock(1_000);
        c.key(Key::CtrlC);
        c.key(Key::CtrlC);
        assert!(c.quit_card);
        assert_eq!(c.key(Key::Esc), None);
        assert!(!c.quit_card, "esc closed it");
        assert!(!c.quit, "and the head is staying");
    }

